var gunY=ty-20+(ads?-1:0);
// v23.xx (gfx14), HIS ORDER (2026-10-12) on the graphics program, item 3, the animation pass: RECOIL. A shot used to show
// only as a muzzle disc; the gun never moved. Now each shot kicks it: the gun goes back 2.2 along the aim and its muzzle
// rises 0.12 radians, and the shoulder gives 0.6, all easing out as the kick fades. The kick is the shooter's own recoil
// (p.recoil, 1 on a shot, gone in a seventh of a second) or, for a pillager, his muzzle timer. Drawn only: the aim, the
// spread and every bullet are exactly as before.
var _rk=(st.recoil!==undefined)?st.recoil:((muzzle>0)?muzzle/0.06:0); _rk=(isFinite(_rk)&&_rk>0)?Math.min(1,_rk):0;
if(mode==='none'||mode==='crouchnone'||mode==='fist') _rk=0;
wc.save(); wc.translate(x+leanX-Math.cos(face)*0.6*_rk,gunY-Math.sin(face)*0.6*_rk); wc.rotate(face+fl*drop-fl*0.12*_rk);
var ext=(ads?2.5:(sprint&&!rl?-3:0))-2.2*_rk;

