{v:'VER',what:'graphics program gfx14 (gun recoil): a shot kicks the gun back at least 1.5 along the aim and tips the muzzle up, for the player through his recoil and for a pillager through his muzzle timer; empty hands do not kick; the raid hands the player recoil to the painter',
 run:function(){
   if(typeof drawOp!=='function') return 'SKIP: no painter here';
   var bad=[], w0=wc, cvs=document.createElement('canvas'), x2, bar=[], oFR, od=drawOp, g, seen=null, r0=null, i;
   cvs.width=240; cvs.height=220; x2=cvs.getContext('2d'); if(!x2) return 'SKIP: no canvas';
